INSERT OR IGNORE INTO categories (slug, name_ar, name_fr, name_en, image, sort) VALUES ('ceramique-zellige', 'خزف الزليج', 'Céramique zellige', 'Zellige ceramics', '/assets/photos/cat-souk.webp', 0);
