INSERT OR IGNORE INTO categories (slug, name_ar, name_fr, name_en, image, sort) VALUES ('decoration', 'الديكور', 'Décoration', 'Home decor', '/assets/photos/cat-decor.webp', 2);
INSERT OR IGNORE INTO categories (slug, name_ar, name_fr, name_en, image, sort) VALUES ('cadeaux', 'هدايا وعلب', 'Cadeaux & coffrets', 'Gifts & boxes', '/assets/photos/cat-gifts.webp', 3);
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('tasse-expresso-soucoupe-morocco', (SELECT id FROM categories WHERE slug = 'art-de-la-table'), 'فنجان قهوة مع صحن «Morocco»', 'Tasse expresso et soucoupe « Morocco »', '“Morocco” espresso cup and saucer', '<p>فنجان قهوة أبيض مكسو بفسيفساء من النجوم الثمانية، وكلمة MOROCCO حول ميدالية في الوسط.</p><p>ويستعيد الصحن الورود الكبيرة للزليج بالأحمر والأزرق والأصفر والأخضر. حجم جميل لقهوة الصباح أو لنص نص بعد الأكل.</p>', '<p>Une tasse expresso blanche habillée d''une mosaïque d''étoiles à huit branches, avec le mot MOROCCO autour d''un médaillon central.</p><p>La soucoupe reprend les grandes rosaces du zellige en rouge, bleu, jaune et vert. Un joli format pour le café du matin ou un nus-nus après le repas.</p>', '<p>A white espresso cup dressed in a mosaic of eight-pointed stars, with the word MOROCCO around a central medallion.</p><p>The saucer echoes the large zellige rosettes in red, blue, yellow and green. A lovely size for the morning coffee or a nus-nus after a meal.</p>', 79, NULL, 24, '', '["/assets/photos/espresso-cup-saucer.webp"]', 0, 0, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-0 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('bougie-petales-de-rose-boite-zellige', (SELECT id FROM categories WHERE slug = 'decoration'), 'شمعة ببتلات الورد في علبة زليج', 'Bougie aux pétales de rose, boîte zellige', 'Rose petal candle in a zellige tin', '<p>شمع أبيض مزيّن ببتلات ورد مجففة، مصبوب في علبة معدنية دائرية مطبوعة بنجوم الزليج بالأخضر والمغرة والعنابي والأسود.</p><p>يحمي الغطاء الشمعة بين الاستعمالات، وتصبح العلبة بعد انتهائها مكاناً أنيقاً للحفظ.</p>', '<p>La cire blanche est décorée de pétales de rose séchés, coulée dans une boîte métallique ronde imprimée d''étoiles zellige en vert, ocre, bordeaux et noir.</p><p>Le couvercle protège la bougie entre deux utilisations et fait de la boîte un joli rangement une fois la bougie terminée.</p>', '<p>White wax decorated with dried rose petals, poured into a round metal tin printed with zellige stars in green, ochre, burgundy and black.</p><p>The lid protects the candle between uses, and the tin makes a pretty keepsake box once the candle is finished.</p>', 89, NULL, 30, '', '["/assets/photos/rose-candle-tin.webp"]', 0, 1, 'inspired', 'شمع، بتلات ورد مجففة، علبة معدنية مطبوعة بغطاء. لا تترك الشمعة مشتعلة دون مراقبة. ضعها على سطح ثابت بعيداً عن المواد القابلة للاشتعال.', 'Cire, pétales de rose séchés, boîte métallique imprimée avec couvercle. Ne jamais laisser une bougie allumée sans surveillance. Poser sur une surface stable, loin des objets inflammables.', 'Wax, dried rose petals, printed metal tin with lid. Never leave a burning candle unattended. Place on a stable surface away from flammable objects.', datetime('now', '-1 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('assiette-decorative-medaillon-zellige', (SELECT id FROM categories WHERE slug = 'decoration'), 'صحن ديكور بميدالية الزليج', 'Assiette décorative médaillon zellige', 'Zellige medallion decorative plate', '<p>ثماني لوحات وثماني تركيبات: ورود زرقاء، ونجوم سوداء وذهبية، وأقواس فيروزية… حول ميدالية كبيرة بالأحمر والأخضر والزعفراني.</p><p>توضع على البوفيه أو تعلّق على الحائط أو تُستعمل كقاعدة ديكور للأطباق.</p>', '<p>Huit panneaux, huit compositions : rosaces bleues, étoiles noires et or, arcs turquoise… autour d''un grand médaillon rouge, vert et safran.</p><p>À poser sur un buffet, à accrocher au mur ou à utiliser comme dessous de plat décoratif.</p>', '<p>Eight panels, eight compositions: blue rosettes, black and gold stars, turquoise arches… around a large red, green and saffron medallion.</p><p>Display it on a sideboard, hang it on the wall, or use it as a decorative trivet.</p>', 129, NULL, 15, '', '["/assets/photos/medallion-plate.webp"]', 1, 2, 'inspired', 'قاعدة صلبة بسطح مطبوع وزخارف ذهبية بارزة. يُمسح بقطعة قماش ناعمة وجافة.', 'Support rigide à surface imprimée, motifs en relief doré. Essuyer avec un chiffon doux et sec.', 'Rigid base with a printed surface and raised gold details. Wipe with a soft, dry cloth.', datetime('now', '-2 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('tasse-embleme-etoile-coffret', (SELECT id FROM categories WHERE slug = 'cadeaux'), 'فنجان بشعار النجمة في علبة', 'Tasse emblème étoilé en coffret', 'Star emblem cup in a gift box', '<p>يحمل الفنجان النجمة الخضراء على ميدالية حمراء بإطار ذهبي، تحيط بها فسيفساء ملونة وإفريز ذهبي للقوافل.</p><p>ويُقدَّم في علبة مربعة بنافذة شفافة ومزخرفة بالزليج من الداخل: هدية جاهزة للإهداء.</p>', '<p>La tasse porte l''étoile verte sur un médaillon rouge cerclé d''or, entourée d''une mosaïque colorée et d''une frise dorée de caravanes.</p><p>Elle est présentée dans un coffret carré à fenêtre transparente, décoré de zellige à l''intérieur : un cadeau prêt à offrir.</p>', '<p>The cup carries the green star on a gold-rimmed red medallion, surrounded by a colourful mosaic and a gold caravan frieze.</p><p>It comes in a square box with a clear window and a zellige-printed interior: a ready-to-give present.</p>', 119, NULL, 18, '', '["/assets/photos/star-cup-giftbox.webp"]', 0, 3, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-3 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('planche-de-service-zellige-a-poignee', (SELECT id FROM categories WHERE slug = 'art-de-la-table'), 'لوح تقديم زليج بمقبض', 'Planche de service zellige à poignée', 'Zellige serving board with handle', '<p>وردة بأشعة زرقاء وحمراء، يحيط بها إطار من النجوم والتشابكات، تمتد حتى المقبض. ويسمح ثقب المقبض بتعليقها في المطبخ.</p><p>لتقديم المسمن أو الحلويات أو الفواكه الجافة، أو كقطعة للزينة.</p>', '<p>Une rosace en rayons bleus et rouges, encadrée d''étoiles et d''entrelacs, s''étend jusqu''au manche. Le trou dans la poignée permet de la suspendre en cuisine.</p><p>Pour présenter des msemen, des gâteaux ou des fruits secs, ou comme pièce décorative.</p>', '<p>A rosette of blue and red rays, framed by stars and interlacing, runs all the way to the handle. The hole in the handle lets you hang it in the kitchen.</p><p>For serving msemen, pastries or dried fruit, or as a decorative piece.</p>', 149, NULL, 12, '', '["/assets/photos/serving-paddle.webp"]', 0, 4, 'inspired', 'لوح بسطح مزخرف لامع وحافة بلون الخشب. يُمسح بقطعة قماش مبللة. لا يُترك في الماء.', 'Planche à surface décorée brillante, bordure couleur bois. Essuyer avec un chiffon humide. Ne pas laisser tremper.', 'Board with a glossy decorated surface and a wood-tone edge. Wipe with a damp cloth. Do not soak.', datetime('now', '-4 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('mini-assiette-embleme-morocco', (SELECT id FROM categories WHERE slug = 'cadeaux'), 'صحن صغير بشعار «Morocco»', 'Mini assiette emblème « Morocco »', '“Morocco” emblem mini plate', '<p>تذكار مشرق: النجمة الخضراء في وسط ميدالية حمراء تحمل كلمة MOROCCO، تحيط بها ورود صفراء وحمراء وزرقاء على خلفية فيروزية.</p><p>مناسب للحقيبة أو للإهداء مع فنجان متناسق.</p>', '<p>Un souvenir lumineux : l''étoile verte au centre d''un médaillon rouge où s''inscrit MOROCCO, entourée de rosaces jaunes, rouges et bleues sur fond turquoise.</p><p>À glisser dans une valise ou à offrir avec une tasse assortie.</p>', '<p>A bright keepsake: the green star in a red medallion inscribed MOROCCO, surrounded by yellow, red and blue rosettes on turquoise.</p><p>Easy to pack in a suitcase, or to give with a matching cup.</p>', 49, NULL, 40, '', '["/assets/photos/star-mini-plate.webp"]', 0, 5, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-5 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('coffret-mug-arc-de-fes-et-cuillere', (SELECT id FROM categories WHERE slug = 'cadeaux'), 'علبة كوب «قوس فاس» مع ملعقة', 'Coffret mug « Arc de Fès » et cuillère', '“Fez Arch” mug and spoon gift set', '<p>يستعيد الكوب شكل قوس المدرسة بفسيفساء زرقاء، مقابل جدار من الورود الصفراء والخضراء والحمراء.</p><p>ويأتي مع ملعقة خزفية حمراء في علبة مزخرفة بالكامل بالزليج مع إفريز من الخط.</p>', '<p>Le mug reprend la silhouette d''un arc de médersa, en mosaïque bleue, face à un mur de rosaces jaunes, vertes et rouges.</p><p>Il est livré avec une cuillère en céramique rouge dans un coffret entièrement décoré de zellige, avec une frise de calligraphie.</p>', '<p>The mug follows the outline of a madrasa arch in blue mosaic, facing a wall of yellow, green and red rosettes.</p><p>It comes with a red ceramic spoon in a box decorated with zellige throughout, with a calligraphy frieze.</p>', 149, NULL, 20, '', '["/assets/photos/arch-mug-spoon-box.webp"]', 1, 6, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-6 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('mug-i-love-morocco', (SELECT id FROM categories WHERE slug = 'ceramique-zellige'), 'كوب «I ♥ Morocco»', 'Mug « I ♥ Morocco »', '“I ♥ Morocco” mug', '<p>لمسة مرحة وملونة: I ♥ MOROCCO على خلفية زليج حمراء وخضراء وزرقاء وسوداء، مع إفريز من المعيّنات على الحافة وداخل أحمر.</p><p>شكله المنحني مريح في اليد، ومقبضه على شكل لولبي.</p>', '<p>Un clin d''œil gai et coloré : I ♥ MOROCCO sur un fond de zellige rouge, vert, bleu et noir, avec une frise de losanges au bord et un intérieur rouge.</p><p>Sa forme galbée tient bien en main, son anse est façonnée en volutes.</p>', '<p>A cheerful, colourful nod: I ♥ MOROCCO on a red, green, blue and black zellige background, with a lozenge frieze at the rim and a red interior.</p><p>Its curved shape sits well in the hand, and the handle is shaped in scrolls.</p>', 99, NULL, 26, '', '["/assets/photos/i-love-morocco-mug.webp"]', 1, 7, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-7 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('coffret-duo-de-mugs-embleme-etoile', (SELECT id FROM categories WHERE slug = 'cadeaux'), 'علبة زوج أكواب بشعار النجمة', 'Coffret duo de mugs emblème étoilé', 'Star emblem mug duo gift box', '<p>تحتوي كل علبة على كوبين متناسقين، مزيّنين بميداليات حمراء بالنجمة وفسيفساء زليج وإطار ذهبي. وتذكّر المقابض المموجة بأقواس الرياض.</p><p>تُحمل العلبة المزخرفة بالزليج بحبلها: مثالية للإهداء. ثلاث زخارف للاختيار.</p>', '<p>Chaque coffret contient deux mugs assortis, ornés de médaillons rouges à l''étoile, d''une mosaïque zellige et d''un filet doré. Les anses festonnées rappellent les arcs des riads.</p><p>Le coffret décoré de zellige se porte grâce à sa cordelette : idéal à offrir. Trois décors au choix.</p>', '<p>Each box holds two matching mugs decorated with red star medallions, a zellige mosaic and gold trim. The scalloped handles recall the arches of riads.</p><p>The zellige-printed box has a rope handle for carrying: ideal as a gift. Three designs to choose from.</p>', 189, 219, 17, '[{"name":{"fr":"Décor","ar":"الزخرفة","en":"Design"},"type":"text","values":[{"label":"Médaillon doré et bleu","price":0},{"label":"Rosaces vertes et bleues","price":0},{"label":"Grande rosace rouge","price":0}]}]', '["/assets/photos/twin-mug-set-box.webp","/assets/photos/twin-mug-sets-display.webp","/assets/photos/twin-mug-set-side.webp"]', 1, 8, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-8 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('petit-mug-expresso-et-cuillere-rouge', (SELECT id FROM categories WHERE slug = 'ceramique-zellige'), 'كوب قهوة صغير مع ملعقة حمراء', 'Petit mug expresso et cuillère rouge', 'Espresso mug with red spoon', '<p>ورود حمراء وصفراء وخضراء، وميداليتان بالنجمة، وإفريز ذهبي في الأعلى والأسفل.</p><p>توضع الملعقة الحمراء الصغيرة في المقبض: عملية للقهوة أو الحليب الساخن.</p>', '<p>Rosaces rouges, jaunes et vertes, deux médaillons à l''étoile et une frise dorée en haut et en bas.</p><p>La petite cuillère rouge se range dans l''anse : pratique pour le café ou le lait chaud.</p>', '<p>Red, yellow and green rosettes, two star medallions and a gold frieze at the top and bottom.</p><p>The little red spoon slots into the handle: handy for coffee or hot milk.</p>', 69, NULL, 35, '', '["/assets/photos/espresso-mug-spoon.webp"]', 0, 9, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-9 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('duo-de-tasses-ecrin-noir', (SELECT id FROM categories WHERE slug = 'cadeaux'), 'زوج فناجين في علبة سوداء', 'Duo de tasses en écrin noir', 'Cup duo in a black presentation box', '<p>يجمع الفنجانان بين فسيفساء خضراء وحمراء وصفراء وميداليات كبيرة بالنجمة. ويستقران في علبة سوداء مقسّمة مزخرفة بالزليج من الخارج.</p><p>تقديم أنيق لهدية عيد ميلاد أو عرس أو شكر.</p>', '<p>Les deux tasses associent une mosaïque verte, rouge et jaune à de grands médaillons à l''étoile. Elles reposent dans un écrin noir compartimenté, à l''extérieur décoré de zellige.</p><p>Une présentation soignée pour un cadeau d''anniversaire, de mariage ou de remerciement.</p>', '<p>Both cups pair a green, red and yellow mosaic with large star medallions. They rest in a black compartmented box, decorated with zellige on the outside.</p><p>A polished presentation for a birthday, wedding or thank-you gift.</p>', 169, NULL, 14, '', '["/assets/photos/duo-cups-black-box.webp"]', 0, 10, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-10 hours'));
INSERT OR IGNORE INTO products (slug, category_id, name_ar, name_fr, name_en, desc_ar, desc_fr, desc_en, price, compare_price, stock, options, images, featured, sort, craft, materials_ar, materials_fr, materials_en, created_at) VALUES ('mug-ondule-embleme-etoile', (SELECT id FROM categories WHERE slug = 'ceramique-zellige'), 'كوب متموّج بشعار النجمة', 'Mug ondulé emblème étoilé', 'Wavy star emblem mug', '<p>شكل مبتكر كبلاطة زليج متموّجة: نجوم ثمانية حمراء وزرقاء فاتحة وسوداء على خلفية بيضاء، وميداليتان بالنجمة وإطار ذهبي.</p><p>قطعة لافتة على المكتب أو الرف.</p>', '<p>Une forme originale, comme un carreau de zellige qui ondule : étoiles à huit branches rouges, bleu ciel et noires sur fond blanc, deux médaillons à l''étoile et une bordure dorée.</p><p>Une pièce graphique qui se remarque sur un bureau ou une étagère.</p>', '<p>An original shape, like a rippling zellige tile: red, sky-blue and black eight-pointed stars on white, two star medallions and a gold border.</p><p>A graphic piece that stands out on a desk or shelf.</p>', 89, NULL, 4, '', '["/assets/photos/wave-mug-star.webp"]', 0, 11, 'inspired', 'خزف أبيض مزجّج بزخرفة زليج مطبوعة ولمسة نهائية لامعة. يُغسل برفق باليد باستعمال إسفنجة ناعمة. تجنّب المنظفات الخشنة للحفاظ على الزخرفة.', 'Céramique émaillée blanche, décor zellige imprimé, finition brillante. Laver délicatement à la main avec une éponge douce. Éviter les produits abrasifs pour préserver le décor.', 'White glazed ceramic with a printed zellige decoration and glossy finish. Wash gently by hand with a soft sponge. Avoid abrasive products to protect the decoration.', datetime('now', '-11 hours'));
